import {spawn} from 'node:child_process';
import {createInterface} from 'node:readline';
import {mkdir,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
const base=resolve('.acp-plan-research');
async function probe(name,command,args,extra={}) {
 const home=resolve(base,'homes',name); await mkdir(home,{recursive:true});
 const env={PATH:resolve(base,'node_modules/.bin')+':'+process.env.PATH,HOME:home,XDG_CONFIG_HOME:home+'/.config',XDG_DATA_HOME:home+'/.local/share',XDG_CACHE_HOME:home+'/.cache',PI_CODING_AGENT_DIR:home+'/.pi/agent',COPILOT_HOME:home+'/.copilot',COPILOT_AUTO_UPDATE:'false',NO_COLOR:'1',...extra};
 for(const k of ['LD_LIBRARY_PATH','NIX_LD','NIX_LD_LIBRARY_PATH','SSL_CERT_FILE']) if(process.env[k]) env[k]=process.env[k];
 const child=spawn(command,args,{env,cwd:base,stdio:['pipe','pipe','pipe'],detached:true});
 const result={name,command,args,environment:extra,frames:[],stderr:'',exit:null};const pending=new Map();let id=0;
 const lines=createInterface({input:child.stdout});
 lines.on('line',line=>{try{const v=JSON.parse(line);result.frames.push(v);if(v.id!=null&&pending.has(v.id)){pending.get(v.id)(v);pending.delete(v.id);}if(v.method&&v.id!=null){child.stdin.write(JSON.stringify({jsonrpc:'2.0',id:v.id,result:{outcome:{outcome:'cancelled'}}})+'\n');}}catch{result.frames.push({nonJson:line.slice(0,512)});}});
 child.stderr.on('data',d=>{result.stderr=(result.stderr+d).slice(0,4096);});child.on('error',e=>{result.error=e.message;}); child.on('exit',(code,signal)=>{result.exit={code,signal};});
 const request=(method,params)=>new Promise((resolve,reject)=>{const n=++id; const timer=setTimeout(()=>{pending.delete(n);reject(new Error('timeout '+method));},25000);pending.set(n,v=>{clearTimeout(timer);resolve(v);});child.stdin.write(JSON.stringify({jsonrpc:'2.0',id:n,method,params})+'\n');});
 try{result.initialize=await request('initialize',{protocolVersion:1,clientInfo:{name:'heimdall-planning-probe',version:'1'},clientCapabilities:{fs:{readTextFile:false,writeTextFile:false},terminal:false}});
 if(result.initialize.result) {result.newSession=await request('session/new',{cwd:home,mcpServers:[]});result.steering=await request('_session/steering',{sessionId:result.newSession.result?.sessionId??'missing',prompt:[{type:'text',text:'probe'}],_meta:{steering:{idleBehavior:'promptRequired'}}});}
 }catch(e){result.error=e.message;}
 try{process.kill(-child.pid,'SIGTERM');}catch{} if(child.exitCode===null && child.signalCode===null) await new Promise(r=>child.once('close',r)); lines.close();
 await writeFile(resolve(base,name+'.json'),JSON.stringify(result,null,2)+'\n');
 console.log(JSON.stringify({name,initialize:result.initialize,newSession:result.newSession,steering:result.steering,error:result.error,exit:result.exit,stderr:result.stderr.slice(0,600)}));
}
await probe('copilot','/nix/store/h4wfwic161kxrr74jlzla5lsm28hgary-glibc-2.44-25/lib/ld-linux-x86-64.so.2',['--library-path','/nix/store/h4wfwic161kxrr74jlzla5lsm28hgary-glibc-2.44-25/lib:/nix/store/j7qx4s4mr17j1wqgvqdzj33lmrnzb387-gcc-16.2.0-lib/lib',resolve(base,'node_modules/@github/copilot-linux-x64/copilot'),'--acp','--stdio']);
await probe('pi','node',[resolve(base,'node_modules/pi-acp/dist/index.js')],{PI_ACP_PI_COMMAND:'/nix/store/n9cshyawg2r7bmsp2vgz8787m5n6fpzq-pi-coding-agent-1.1.0/bin/pi'});
await probe('pi-embedded','node',[resolve(base,'node_modules/pi-acp/dist/index.js')],{PI_ACP_PI_COMMAND:'/nix/store/n9cshyawg2r7bmsp2vgz8787m5n6fpzq-pi-coding-agent-1.1.0/bin/pi',PI_ACP_ENABLE_EMBEDDED_CONTEXT:'true'});

